import os,glob,re,os.path
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); print(G.get('Test input'))

def pipe_info(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    def runs(color, orient):
        res=[]
        if orient=='h':
            for r in range(H):
                c=0
                while c<W:
                    if g[r][c]==color:
                        c0=c
                        while c<W and g[r][c]==color: c+=1
                        res.append((r,c0,c-1)); 
                    else: c+=1
        else:
            for c in range(W):
                r=0
                while r<H:
                    if g[r][c]==color:
                        r0=r
                        while r<H and g[r][c]==color: r+=1
                        res.append((c,r0,r-1))
                    else: r+=1
        return res
    for color,cn in cnt.most_common():
        if color==bg: continue
        h=runs(color,'h'); v=runs(color,'v')
        if len(h)==2 and not v: return bg,color,'h',h
        if len(v)==2 and not h: return bg,color,'v',v
    return None

def transform(g):
    H,W=len(g),len(g[0])
    bg,pc,orient,segs=pipe_info(g)
    seed_color=[c for c in Counter(x for row in g for x in row) if c not in (bg,pc)][0]
    out=[row[:] for row in g]
    for sr in range(H):
        for sc in range(W):
            if g[sr][sc]!=seed_color: continue
            if orient=='h':  # horizontal pipe rows -> vertical beams
                cand=[s for s in segs if s[1]<=sc<=s[2]]
                tgt=cand[0]
                d=1 if tgt[0]>sr else -1
                r=sr+d
                while 0<=r<H and g[r][sc]==bg:
                    out[r][sc]=seed_color; r+=d
                idx=sc-tgt[1]
                other=[s for s in segs if s is not tgt][0]
                ec=other[1]+idx
                r=other[0]+d
                while 0<=r<H and g[r][ec]==bg:
                    out[r][ec]=seed_color; r+=d
            else:
                cand=[s for s in segs if s[1]<=sr<=s[2]]
                tgt=cand[0]
                d=1 if tgt[0]>sc else -1
                c=sc+d
                while 0<=c<W and g[sr][c]==bg:
                    out[sr][c]=seed_color; c+=d
                idx=sr-tgt[1]
                other=[s for s in segs if s is not tgt][0]
                er=other[1]+idx
                c=other[0]+d
                while 0<=c<W and g[er][c]==bg:
                    out[er][c]=seed_color; c+=d
            out[sr][sc]=4
    return out

